INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1252225-engl102', 'stk-practice', 'ENGL 102', 'info', '{"desc": "كورس ثقيل قي الترم العادي وخفيف في الصيف\n\nانا اخذته صيف ولا حسيت فيه نهائيا\n\nطبعا مع مراعاة الدكتور اللي يخلص سريع سريع واللي يطول الهرجة وهيا ما تحتاج", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/12", "user": "Practice", "ts": 1376193406000, "tid": 120479, "pn": 12}}', 1376193406000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1260946-engl102', 'stk-legend22', 'ENGL 102', 'info', '{"desc": "كورس ممتع للي يحب الانجليزي\nتركيزه الاكبر على كتابة التقرير .\nمهم جدا انك تختار المصادر الجيدة و تقيمها\nالمدرس مهم جدا جدا في هذا الكورس\nالله يوفقكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/13", "user": "Legend22", "ts": 1378572547000, "tid": 120479, "pn": 13}}', 1378572547000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316516-engl102', 'stk-_716', 'ENGL 102', 'info', '{"desc": "الكورس هذا مافيه توفل …\n\nمشكلة الكورس أنه لازم تنزله مع مدرس يريحك وخصوصاً لو أنقليزيتك متوسطة أو ضعيفة\n\nلأنك راح تتعب مع المدرسين اللي يكرفون وراح تشتغل على الانجلش بدلاً من الماث والفزكس وفي النهاية تاخذ لك c ولا c+\n\nنصيحة من أخ لأخوة لأني عانيت مع مدرس يكررررف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/16", "user": "_716", "ts": 1389086081000, "tid": 120479, "pn": 16}}', 1389086081000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317413-engl102', 'stk-guest', 'ENGL 102', 'info', '{"desc": "الكورس أثقل من 101 و السبب الرئيسي هو الريبورت طبعا اذا نزلت مع دكتور راعي هومووركات بيصير أثقل كثييير فابعد عنهم أحسن لك، امشي في الريبورت زي ما يقول دكتورك وراجعه دايما عشان تاخذ قريد عالي في الريبورت ، الميد تيرم والفاينل ريدنغ فما في شي تذاكر له فعليا قبلهم ، من الدكاترة الجيدين اللي ينزلوا الكورس jonthan marqouis & miachael stowe", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/17", "user": "Guest", "ts": 1389201163000, "tid": 120479, "pn": 17}}', 1389201163000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1371961-engl102', 'stk-mhm14', 'ENGL 102', 'info', '{"desc": "Term 132\n\nالكورس هذا يركز أكثر شيء على كتابة الريبورت، و عادة الموضوع العام عن الريبورت يختلف من ترم لآخر و الدكتور يحدد لك الموضوع اللي بتكتب عنه\nبعدها بتدور على 4 مصادر كحد أدنى و تقيمهم حتى تستخدمهم في الريبورت اللي بتكتبه، و عادة الطلاب يخافوا من البليجرزم لكن إذا سويت paraphrase للجمل اللي بتستخدمها و تذكر المصادر هذا بيبعدك عن شبهة الغش و بتكون مرتاح\n\nطبعا الدكتور بيستخدم موقع turn it in و هذا الموقع يكشف لك من نسبة النقل بالنص من مصادر ثانية في أنحاء العالم و كذلك من طلاب الجامعة و لذلك المفروض الطالب ما يفكر ينقل شيء من أحد ثاني أو حتى من كتاب أو موقع في النت لأن هذا الموقع بيكشف كل شيء\n\nطبعا الدكتور بيعطيك الموقع تستخدمه لفترة معينة حتى تشوف إذا عندك نقل أو شيء و تعدل عليه و تستخدمه أكثر من مرة و ما راح يحفظه في السيستم ، لكن في نهاية الترم بيحط لك الموقع من الجديد لكن للـFinal check و في هذي الحالة ما بتقدر تعدل عليها و بتنحفظ في السيستم، و بعدها بيطلب منك تجيب نسخة ورقية للريبورت مع كل المستندات اللي استعملتها في الريبورت و يقيمك عليه\n\nو كتابة الريبورت تكون على ثلاث كلاسات، كل مرة يصحح لك الدكتور و يطلب منك تقدم كتابة أفضل و في النهاية ترتب الأقسام و تسلمها\nو أنصح الطلاب إنهم ما يأجلوا أبدا في كل قسم يكتبوه، بس تكتب القسم و يصححها الدكتور و يرجعها على طول عدل عليها و لا تأجل شي و لا بتشوف نفسك على آخر لحظة تبغى تلحق تخلص و ما راح تخلص\n\nو في آخر اسبوع بتقدم عرض عن جزء من الريبورت اللي كتبته و بتنسأل أسئلة من الطلاب و المدرس فكون محضر لهذا الشي\nو طبعا الكورس فيه كويزات ريدنغ و رايتنغ و هذي تكون في القسم الأول من الترم و القسم الثاني تتفرغ للريبورت\n\nالكورس و إن كان ثقيل نوعا ما بس استمتعت فيه أكثر من 101 و الدرجات في هالكورس أسهل إنك تحصلها مقارنة بـ101\nو أنصح الطلاب إنهم ما يأجلوا الكورس و ياخذوها في أقرب وقت حق يرتاحوا منه\n\nالقريد النهائي: B", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/19", "user": "MHM14", "ts": 1401099640000, "tid": 120479, "pn": 19}}', 1401099640000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1372332-engl102', 'stk-user8581', 'ENGL 102', 'info', '{"desc": "جودة المقرر بشكل عام\nيحكم ان الكورس ماله كتاب معين فهو يعتمد على الدكتور الي منزل معاه …\n\nالمواضيع التي يغطيها المقرر\nتقريبا مشابه لـ 101 اللهم الريبورت الي راح ياخذ وقت شوي خصوصا اذا كنت منزل عند دكتور كرييف …\n\nالكتاب المستخدم للمقرر\nلايوجد …\nالأسئلة والأمثلة المستخدمة في المقرر\nلايوجد …\n\nمدى فائدته في الناحية التطبيقية\nمثل ما ذكرت الفائدة تعتمد على دكتورك بس بشكل عام فادني في التنسيق وصياغة وتقسيم الافكار الي راح اغطيها في اي ريبورت …\n\nإضافات :\nاذا مستواك عال حاول تنزل مع دكتور مب كريف ويعطي قريدات محترمة مقارنة ببقية الدكاترة الي معلقين على الـ c و d+ ولا تنزل مع دكتور راع كرف وشغل وفي النهاية يعطيك قريد ماتستحقه … هالكورس يعتمد على دكتوركك بشكل كبير يمكن يصير علة وغثيث ويمكن يصير ماي ولا كأنك منزل مادة اسمها انجلش فحاول تختار دكتورك بدقة …\n+\nاذا بديت في الريبورت حاول لا تأجل فيه شي ولا تسوي شغل اي كلام لأنه راح تكون مضغوط في مواد ثانية و تبي تستعد للفاينلات فبتضطر انك تسحب عليه او ماتسويه بالطريقة الي يبها دكتورك + البرزنتيشن راح يكون عن الريبورت يعني لو جبت العيد في الريبورت احتمال كبير تجيب العيد في البرزنتيشن + اذا كان موضوع مالها سورسات كثيرة وقوية نصيحة كلم دكتورك وحاول تغيره لأنك راح تتوهق خصوصا اذا بديت في الدرافت ماراح تلقى شي تكتب عنه\n\nوهذا تقسيم الدرجات ( المرفقات )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/20", "user": "user8581", "ts": 1401142717000, "tid": 120479, "pn": 20}}', 1401142717000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1439403-engl102', 'stk-user9534', 'ENGL 102', 'info', '{"desc": "نفس 101 بس هذا فيه ريبورت (تقرير) 😆\n\nبيعلمونك كيف تجيب مصادر للتقرير حقك وكيف تضبطه فلذلك لاتشيل همه 😆\n\nأهم شيء دور مدرررررررررس مايكرف ويعطي قريدات 😆 وأمورك بتصير سهالات اذا نزلت عند مدرس طيب 🙂\n\nأما لو نزلت عند مدرس خبيث … الريبورت بيصير أخس من مياجر الفيزكس , لأنه بيعقد السالفة وبيحسسك أنه تقرير لوكالة ناسا مو طالب 😦", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/21", "user": "user9534", "ts": 1453073548000, "tid": 120479, "pn": 21}}', 1453073548000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1457242-engl102', 'stk-m_nd_m', 'ENGL 102', 'info', '{"desc": "ENGL 102 - T153\n\nجودة المقرر بشكل عام/\nالمقرر ممتاز مفيد و بتلاحظ تطور مستواك خلاله\n\nالمواضيع التي يغطيها المقرر/\nReading & writing\nBut mainly report writing\n\nالكتاب المستخدم للمقرر/\n-----\n\nالأسئلة والأمثلة المستخدمة في المقرر/\n-----\n\nمدى فائدته في الناحية التطبيقية/\nمثل ما قلت مستواك بتطور… تحديدًا بالرايتينج\n\nملاحظات عامة/\nالمشكلة الرئيسية بهالكورس أن كل دكتور يطلب طلبات مختلفة من طلاب أي دكتور ثاني… يعني كل دكتور يحسب أنه طريقته هي الصحيحة و الباقيين كلهم غلط\n\n+\n\nدرجة الريبورت تتوزع على أكثر من قسم:\n1- Note Cards\n2- ٍSource Evalutions\n3- Rough Draft\n4- Soft&Hard Copy Report\nتقريبًا كل قسم 5%\n(يمكن تختلف من صيفي لترم عادي)\n\nنصائح ذهبية/\n1- حاول تطبق اللي يطلبه الدكتور بالحرف\n2- إذا في شي ما فهمته أسأل الدكتور حتى لو مليون مرة يعني أنشب له لين تفهم\n3- لا تتأخر في كتابة و تجهيز كل ما يتعلق الريبورت و تقول بعدين بعدين بعدين (لا تأجل عمل اليوم إلى الغد)\n\nالسيلابس:\nhttp://c.top4top.net/p_251i0891.png\nhttp://c.top4top.net/p_251i0891.png", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/23", "user": "M_nd_m", "ts": 1473332032000, "tid": 120479, "pn": 23}}', 1473332032000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473958-engl102', 'stk-abdullah2015', 'ENGL 102', 'info', '{"desc": "أخذت الكورس ترم 162\n\nبشكل عام هو زي انجلش 101 لكنه فيه ريبورت …\n\nيقولون إن الريبورت راح يتكنسل بدءًا من ترم 171 ، والكورس كله على الريبورت، فما أدري كيف راح يكون نظام الكورس بدءًا من السمستر القادم\n\nلذلك ما أظن فيه فائدة من إني أكتب تفاصيل أو نصائح بالنسبة لهذا الكورس …\n\nلكن بشكل العام الكورس كله رايتنق … إذا كان مستواك ضعيف في الرايتنق راح تحس إن الكورس ثقيل عليك، بينما اللي يحبون يكتبون كثير بيكون كورس جميل بالنسبة لهم 🙂\n\nبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/24", "user": "Abdullah2015", "ts": 1495972500000, "tid": 120479, "pn": 24}}', 1495972500000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486229-engl102', 'stk-user11164', 'ENGL 102', 'info', '{"desc": "مادة جميلة، ستتعلم فيها بعض مهارات الكتابة النافعة مثل (البحث عن مصادر والتوثق منها، كتابة الإحالات المرجعية، إعادة صياغة النص المقتبس … وغيرها) ، هذه المادة تعتمد بشكل كبير على تأسيسك اللغوي السابق ( مخزون المفردات والعبارات عندك، قدرتك التعبيرية عند الكتابة )، ومع ذلك فإن التميز في هذه المادة ليس مستحيلاً -حتى لمن كان بنيانه اللغوي ضعيفاً- وهو برأيي المتواضع يكمن في ثلاثة أمور بعد التوفيق الإلهي:\n* عدم التسويف وترحيل المهام، مهم جداً هذا الأمر حقيقة\n* عدم التململ والاستسهال في مرحلة ماقبل الكتابة (جمع المصادر، ترتيب الأفكار، كتابة المسودة الأولية)\n* القدرة على إيجاد مصادر قوية تدعّم كتاباتك، والمقدرة على النظر للموضوع الذي ستكتب عنه من منظور غير تقليدي\n\n## وتعقيباً على تعليق أخينا في الأعلى، فإن التقرير Report لم يلغى أو يحذف، إنما تم تقليص الحد الأدنى للكلمات المطلوبة فيه من 1200 إلى 600 كلمة فقط\n\nموفقون .. مسددون .. مؤيدون", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/25", "user": "user11164", "ts": 1516144962000, "tid": 120479, "pn": 25}}', 1516144962000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492308-engl102', 'stk-breaktheunbreakable', 'ENGL 102', 'info', '{"desc": "نفس كلام اللي فوق بس حبيت أقول أن الريبورت صار 600 كلمة بدل 1200 وذا يسهله عليك ويخليك تطلع شيء محترم إن شاء الله. لا تسوف شيء في المادة، المادة متوسطة الصعوبة وتعتمد على مستواك في الإنجليزي بشكل عام.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/26", "user": "BreakTheUnbreakable", "ts": 1526271759000, "tid": 120479, "pn": 26}}', 1526271759000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518650-engl102', 'stk-mr.power', 'ENGL 102', 'info', '{"desc": "بسم الله الرحمن الرحيم …\n\nصراحة المادة هذي جداً جداً مهمة للطالب ، كمية ومقدار الاستفادة من هالكورس جداً عالية على الصعيد الشخصي والوظيفي …\n\nهالمادة راح تعلمك أشياء اكاديمية في اللغة الانجليزية كثيرة ، فعلاً راح تحس بالجو الاكاديمي للغة الانجليزية بهالكورس ، راح تستمع لو كنت شغوف بتعلم شيء راقي باللغة بعيداً عن الكلام العامي اللي طفشنا منه مع الاسف.\n\nوفقكم الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/27", "user": "Mr.power", "ts": 1577953235000, "tid": 120479, "pn": 27}}', 1577953235000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522382-engl102', 'stk-nasalmz', 'ENGL 102', 'info', '{"desc": "term 182\nالكورس هذا هو النقلة النوعية للكتابة الأكاديمية وهو كورس جدا ممل ومهم بنفس الوقت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/28", "user": "Nasalmz", "ts": 1590427010000, "tid": 120479, "pn": 28}}', 1590427010000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527222-engl102', 'stk-abofordan2004', 'ENGL 102', 'info', '{"desc": "TERM 201 ONLINE\n\nكورس جدا ممتاز ولا يحتاج مذاكرة ابدا فقط سوي اللي يقولك عليه الدكتور وامورك في السمبتيك\n\nفي الرايتنق تاسك نفس 101 بالضبط بس الهم انك تجيب مصادر موثوقه وتسوي لها citation\n\nعلى عكس 101 هذا الكورس فيه برزنتيشن و ريبورت وكلها سهالات ان شاء الله\n\nالمادة ماهي معقدة ابدا ولكن تعتمد بشكل كبير على الدكتور بس سوي اللي يقولك عليه ويجيك قريد يبيض الوجه\n\nهذا الكورس ممتاز جدا جدا جدا في الاون لاين وممكن يكون افضل كورس تاخذه اون لاين لعدة اسباب ومنها :\n\n1- كتابة التاسكات والريبورت على مايكروسوفت وورد عكس الحضوري تكون كتابة بخط اليد مما يعني انه بتكون عليك الكتابة والمسح سهل جدا وما تاخذ وقت فيها وكشكل يكون نظيف ومرتب\n2- اهم نقطة انك ما تشيل هم البرزنتيشن والوقفه امام الطلاب, في الاون لاين تسويه عالسرير وانت حاط رجل على رجل والامور عسل\n3- المحاضرات والشرح مسجلة ونرجع لها متى ما بغيت\n\nتوزيع الدرجات :\n\nاثنين ريدنق كويز : 10%\nاثنين رايتنق تاسك : 20%\nميدتيرم : 20%\nريبورت: 20%\nبرزنتيشن : 15%\nفاينل : 15%\n\nملاحظة : تقييمي للكورس للاون لاين فقط ممكن يختلف في الترم الحضوري , اذا رجعت الدراسة حضوري تجاهل هذا التقييم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/29", "user": "AboFordan2004", "ts": 1608701555000, "tid": 120479, "pn": 29}}', 1608701555000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1231424-engl102', 'stk-alhakem', 'ENGL 102', 'info', '{"desc": "term 122\n\n---------------------------\n\nثلاثة ريدنق كوز (15%)\nثلاثة رايتنق تاسك (25%)\nمدترم (15%) (راينق فقط ،يكون مشابه جدا في الاسلوب لرايتنق تاسك 3)\nفاينل (15%) (30 سؤال اختيار من متعدد ريدنق ثلاث قطع)\nشغل الريبورت توتال (20%) مقسمه على النحو التالي:\n4 سورس افاليويشن 5% (تجيب السورسات وتقيمهم :المصدر جديد مثلا، موثوق،اللغة اكاديمية ولا لغة عامية!!…الخ)\nأول درافت للريبورت 5% ( تكتب الريبورت في الكلاس “5-6 كلاسات”)\nكتابة النوت 5% (لكي لا تستخدم سورساتك أثناء الكتابة، تسوي نوتات مع بارافريز\"اعادة صياغة\")\nفاينل درافت 5% (التسليم النهائي للريبورت)\n\nبرزنتيشن (10%) على موضوع الريبورت 3-4دقايق مع بوربوينت\n\nالمجموع 100%****-------------------\n\nالكورس سهل ولكنه يعتمد على قدراتك الكتابية + المدرس بشكل رئيسي… لأن هو اللي بيحط الكوزات الريدنق وهو اللي بيحط راتنق تاسك وهو اللي بيمسك شغل الريبورت(تصحيح وبعض الأحيان اختبار موضوع االريبورت لكل طالب !!) وأخيرا تقييم البرزنتيشن = بيده 70%\nلو بيعطي هوموركات أو يكرف بعد هذا شي ثاني\n\nاضافات:\n-البلاجيرزم (copy-paste) هذا محظور جدا جدا ووقوعك ضحية له بخسف درجاتك(قد تصل الى الـ F )(سواء في المتدترم ، أو الرابتنق تاسك أو في الريبورت)\nالكورس مهم ويعتبر مقدمة لـ 214 أو أي نوع من أنواع البحوث والريبورتات أو بعض الأحيان بروجكترات\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/10", "user": "alhakem", "ts": 1370274784000, "tid": 120479, "pn": 10}}', 1370274784000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1321735-engl102', 'stk-medoalkebsi', 'ENGL 102', 'info', '{"desc": "بالمختصر المفيد , كورس مافيه شي غير ريبورت في الفتره الاخيره من الترم.\n\n3 كوزات ريدنق 15%\n3 كوزات رايتنق 30%\nميدترم(ريدنق) 10%\nالريبورت 20%\nبرزنتيشن 10%\nفاينل.(ريدنق)15%\n\nفاضييين ماعندنا سالفه الا يوم يجي الريبورت , الريبورت هذا انصح من الطلاب بدأوه فيه انهم مايسوفون كثير , يخلصونه بأسرع وقت , لانه يجي وبقت غلط وشوي ياخذ وقت.\n\nالكورس هذا قريدك يعمد على الكوزات لانه تشكل 45%.\nوبالتوفيق … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/18", "user": "Medoalkebsi", "ts": 1390526143000, "tid": 120479, "pn": 18}}', 1390526143000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449559-engl102', 'stk-osamah56', 'ENGL 102', 'info', '{"desc": "Term 152\n\nمن وجهة نظري 102 اسهل من 101 بواااااجد إذا كانت كتابتك كويسة لأن تقريبا 55% من الكورس كتابة:\nReport 20%\nWriting Tasks 20%\nMidterm Exam 15%\n\nويبقى:\nRQs 10%\nPresentation 10%\nFE 25%\n\nأهم شيء بالكورس ذا انك تدور دكتور تصحيحه كويس ومتساهل ( انصح ب John Anyan ), وإذا كانت كتابتك ماهي كويسة حاول تحسنها قبل ما تاخذ الكورس لان هذا الي يخلي الطلاب يحسون الكورس ثقيل.\n\nوشكراً 🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/22", "user": "osamah56", "ts": 1463599839000, "tid": 120479, "pn": 22}}', 1463599839000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p789197-engl102', 'stk-student_nz', 'ENGL 102', 'info', '{"desc": "انجلش 102\n\nهذا الكورس يتعبر اثقل من 101\nلوجود الريبورت فيه\n\nالريبورت واغراضه تقريبا 25 %\n** سورس افالويشن\n** اول درافت\n** الفاينل ريبورت ( 800 -1200 كلمة(\n\nالبريزينتاشن 10 %\nممكن يدمج مع الريبورت ويكون الموضوع اللي راح تتكلم عنه في الريبورت هوا نفس الموضوع الللي تسوي البريزنتاشن عنه >> يعتمد على حسب المدرس\n\nميد تيرم رايتنق 10 %\nفاينل ريدنق 10 %\nتوفل 10%\n2 رايتنق تاسك 10 % لكل واحد\nتوتريال >> انا اخذته بالصيف عشان كذا ما كان عندي توتريال\n\nبالنسبة للتوفل مع بداية السنة الاكاديمة الجديدة\n201 راح يكون التوفل محسوب بدرجة معينة اذا ما جبتها\nما راح يسمح لك النظام انك تروح للانجلش 102\nيعني تروح تدرس برى تاخذه مرة ثانية تتصرف في نفسك اهم شي تجيب الدرجة اللي يطلبها القسم\n\nالكورس\nيركز على الريبورت\nلا تحاول او تفكر انك تاخذ الريبورت من موقع او شي زي كذا لانه يباان للمدرسين من طريقة كتابة الريبورت هذا شي\nالشي الثاني المدرسين يتسعملوا موقع يكشف البلايجرزم( الغش) والشي الثاني لاتاخذ الريبورت من واحد مخلص المادة لانه نفس الشي كل واحد اخذ الكورس يسلم سوفت كوبي للمدرس حقه عشان يحطوه في السستم حق الموقع او البرنامج يعني راح تكون مكشوف.\n\nالكورس ينزل في الصيف\nوانا اشوف انه في الصيف مناسب تاخذه مع مادة عربي او اسلامي لانه لو اخذت مادة ثقيلة معاه راح تتعبك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-102-214/102863/1", "user": "student_NZ", "ts": 1297628617000, "tid": 102863, "pn": 1}}', 1297628617000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1293992-engl102', 'stk-user9292', 'ENGL 102', 'info', '{"desc": "جبت لك العلم الاكيد نزل في البلاك بورد :\n\nENGL102\n\nREGISTERING FOR ENGLISH 102 IN SUMMER\nNovember 25, 2013 8:34 AM\n\nIf you are considering waiting until summer (Term 133) before taking English 102, you should be aware that students need at least a grade C in English 101 before they can register for English 102 in summer. This rule does not apply to registering for English 102 next semester (Term 132).\n\nENGL214****REGISTERING FOR ENGLISH 214 IN SUMMER\nNovember 25, 2013 8:37 AM\nIf you are now in English 102 and are considering doing English 214 this summer, you should be aware that:\n(a) You will need a grade of at least C+ to register for summer school 214.\n(b) You must be second-semester sophomore or later. Freshmen and first-semester sophomores will NOT be allowed to take 214 in summer.\nThese rules do not apply if you wish to take English 214 next semester (Term 132", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-214/152978/1", "user": "user9292", "ts": 1385399250000, "tid": 152978, "pn": 1}}', 1385399250000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1221900-engl102', 'stk-abdullah.d', 'ENGL 102', 'info', '{"desc": "الاختبار راح يكون 35 سؤال\n\nخمس اسئلة منها يجيب لك مثلا جملة وبقولك ايش افضل بارافرايز لها\n\nوبرضوا لا تنسى الدكمونتايشن وو اللي اخذناه طول السمستر\n\nهذا على حسب كلام مدرسنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-finals-engl-102/144371/7", "user": "abdullah.d", "ts": 1368450946000, "tid": 144371, "pn": 7}}', 1368450946000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p789203-engl102', 'stk-student_nz', 'ENGL 102', 'srcU', '{"html": "**نصيحة في كتابة الفيرست درافت للريبورت**<br>انا وجهة نظري و الطريقة اللي اسويها و اعتقد انها الطريقة الامثل<br>انه بعد ما تخلص الاوت لاين حق الريبورت والعنوانين وتكون قرأت السورسات كاااامله<br>وما يبقى الا انك تكتب الريبورت او الفيرست درافت<br><br>اقترح عليك انه تخصص يوم خميس كامل له وتبدأ مثلا الساعة 9 الصباح و ما توقف ليييييييييييين ما يخلص الدرافت كامل لانه زي ما انتوا عارفين الريبورت قطعة تعبير كبيرة فتحتاج ان افكارك تكون متواصلة اذا اخذت بريك تنقطع الافكار حقتك و تنساها وصعب ترجع تتذكرها بعدين حتى لو كتبتها في ورقة صعب انك ترجع تكمل بعدين<br>نصيحتي انك لما تبدأ لا توقف لين تخلص مو مشكلة حتى لو كان في اخطاء الاسبلينق والاشياء زي هذي تسويها بعدين اهم شي افكارك لا توقف وتبقى تفكر كيف تصيغ العبارات و عن ايش النقطة اللي بعدها.<br><br>** التوفل **<br>ركز على اللسينقنق اسهل جزء وتقدر تجمع درجات فيه<br>الصراحة انا ما اعرف اي كتاب له لكن اسال مدرسك او انزل مكتبة جرير في رصة كتب هناك<br>اللي راح يتعبك وعلى قولتهم رصاصة في الراس<br>الريدنق لانه يجي اخر شي وتكون خلاص انت تعبت وما فيك حيل وبعض الاحيان يجيب لك اشياء عن تاريخ امريكيا ممكن يعني ما تعرف عنها شي ومناطق يعني ما يعرفها الا واحد ساكن وعايش في امريكا او يجي الكلمات صعبة و اشياء زي كذا<br>من الاخر يجي اصعب ما في الاختبار<br><br>طيب نفرض ان واحد ما جاب الدرجة اللي يبيها القسم ايش يصير<br>اللي يصير انه ما ينتقل للكورس اللي بعده واذا كان عنده 214 ما يروح كو اب<br><br>توضيح واحد عنده انجلش 102 الدرجة المطلوبة في التوفل هيا 400 من 600 ( الارقام بس امثلة)<br>الرجال جاب 200 من 600 خلاص ما يروح لل214 لين يختبر مرة ثانية ويجيب الدرجة المطلوبة<br>طبعا ما يعتبر عائد للمادة او راسب يعني يدرس بعدين يرجع يختبرها &gt;&gt; هذا على حسب كلام مدرسنا<br><br>بالنسبة للعكس واحد يرسب في الكورس لكن ينجح في التوفل<br>هذي والله ما ادري عنها لانه على حسب كلام مدرسنا ما يصير كذا<br><br>طبعا هذا الكلام مع السنة الاكادمية الجديدة الا اذا صار تعديل او شي يعني<br>ترم 102 و 103 ما يشملهم الكلام هذا<br><br>هذا اللي عندي عن كورسات الانجلش في الجبل الكلام اللي كتبته ممكن صح وممكن غلط<br>و هوا يعبر عن وجهة نظري وتجربة مريت فيها فقط لا غير وحبيت احطها هنا للافادة<br><br>****************** دعواتكم لي ****************", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-102-214/102863/2", "user": "student_NZ", "ts": 1297628718000, "tid": 102863, "pn": 2}}', 1297628718000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p960647-engl102', 'stk-user5571', 'ENGL 102', 'srcU', '{"html": ". English 102 course final exam 5%<br>730am – 830am<br>B54<br>Sunday, 8 January 2012<br><br>Students will receive a 400- to 500-word passage and must perform two tasks: the first is to paraphrase an extract of over 75 words; the second is to write a summary paraphrase of approximately 100 words. Note the instructions below. Students should be clear that for task 2 the summary must paraphrase instead of copying the source words.<br><br>TASK 1<br>Paraphrase the following paragraph. Your paraphrase should be about the same length as the original.<br><br>TASK 2<br>Summarize the following. You must paraphrase. Your summary should be about 100 words long.<br><br>دعواتكم", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-102-final-exam/117638/3", "user": "user5571", "ts": 1325896073000, "tid": 117638, "pn": 3}}', 1325896073000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p851212-engl102', 'stk-abu_3zzoz', 'ENGL 102', 'srcU', '{"html": "final exams, semester 102<br><br>engl102 fe, 10%, 60 minutes<br>students are given a text of about 400-500 words with content related to one of the four core readings (water, carbon, biodiversity, agriculture). The text will probably be taken from a semester 101 student report. Students will write a summary of the entire text in about 100 words. Students will also write a paraphrase of a specified extract. The extract and the paraphrase should be the same size, about 75 words each.<br><br>بالتوفيق<br>🌹", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-practise-final/108227/3", "user": "Abu_3zzoz", "ts": 1307862519000, "tid": 108227, "pn": 3}}', 1307862519000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1046068-engl102', 'stk-sooonah', 'ENGL 102', 'srcU', '{"html": "السلام عليكم ورحمة الله و بركاته<br><br>حبيت اشاركم في هالموضوع يمكن تستفدون منه<br><br>هاذي بعض الخطوات اللي تساعدكم اليوم في الاختبار انشالله<br><br>The goal of writing a summary of an article, a chapter, or a book is to offer as accurately as possible the full sense of the original, but in a more condensed form. A summary restates the author’s main point, purpose, intent, and supporting details i n your own words.<br><br>The process of summarizing enables you to better grasp the original, and the result shows the reader that you understand it as well. In addition, the knowledge gained allows you to better analyze and critique the original.<br><br>First, try to find the main idea in the reading; it’s usually in the first paragraph. Next, skim through the article, glancing at any headings and graphics. Then, read the conclusion. The intent here is both to give yourself a review of the work and t o effectively engage yourself with it.<br><br>Now go back and read the original text carefully, jotting down notes on or highlighting the important points. Write the central idea and the author’s reasons (purpose and intent) for holding this viewpoint. Note the supporting elements the author uses to explain or back up her/his main information or claim.<br><br>Make an outline that includes the main idea and the supporting details. Arrange your information in a logical order, for example, most to least important or chronological. Your order need not be the same as that in the original, but keep related suppo rting points together. The way you organize the outline may serve as a model for how you divide and write the essay.<br><br>Write the summary, making sure to state the author’s name in the first sentence. Present the main idea, followed by the supporting points. The remainder of your summary should focus on how the author supports, defines, and/or illustrates that main ide a. Remember, unless otherwise stated by your instructor, a summary should contain only the author’s views, so try to be as objective as possible.<br><br>As you revise and edit your summary, compare it to the original and ask yourself questions such as: Have I rephrased the author’s words without changing their meaning? Have I restated the main idea and the supporting points accurately and in my own words?<br><br>If you are asked to write a critical summary or to include a critique, you may want to ask yourself questions such as: Does the author succeed? How and why or why not? What are the strengths, weaknesses? Why? What did the author do well? Not well? Why?<br><br>انا اشوف انه اللي باللون الاحمر اهم<br>الخطوات<br><br>دعوااااااااتكم", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/final-for-english-102/126436/1", "user": "sooonah", "ts": 1338121951000, "tid": 126436, "pn": 1}}', 1338121951000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1063775-engl102', 'stk-_special_one', 'ENGL 102', 'srcU', '{"html": "و الله يا اخوي انا الدكتور الي كنت عنده طلب مني 4 سورسات و كلها قدرت اطلعها بيوم واحد من الاون لاين Library الي على موقع الجامعة ( بس الي اذكره عشان تستخدمها لازم تكون داخل الجامعة ) عسى نكون ساعدناك و جاهز لاي استفسار عندك", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/128226/8", "user": "_SpEcIaL_OnE", "ts": 1341405536000, "tid": 128226, "pn": 8}}', 1341405536000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1441280-engl102', 'stk-user10207', 'ENGL 102', 'srcU', '{"html": "اختار موضوع يعجبك واكتب ريبورت عنه.<br><br>الريبورت سهل من ناحية الكتابة وحتى عدد الكلمات.<br>اذا اشتغلت عليه من الحين وحتى موعد التسليم ماراح يكون فيه ضغط.<br>*راح تتعود تكتب بروجكتات وريبورتات طويلة بالجامعة.<br><br>طبعا شوف معلومات عن طريقة كتابة الريبورت، مثلا<br>Professional writing, cover page, table of contents, introductions, references, tables, images, captions graphs,sources, etc<br>وغيرها. اتبع اسلوب الكتاب والمدرس استشيره بالاشياء الي ماتعرفها بالريبورت.", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/172092/3", "user": "user10207", "ts": 1454510073000, "tid": 172092, "pn": 3}}', 1454510073000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1441283-engl102', 'stk-user9248', 'ENGL 102', 'srcU', '{"html": "حاول تختار موضوع يكون له علاقة بتخصصك,<br>مثلاً: لطلاب الميكانيكال:الطاقة المتجددة.<br>المفروض الدكتور يعطيكم قائمة بالمواضيع و تختارو منها, حاول تروح له “الأوفيس أور” و تطلب منه يساعدك 🌹 .", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/172092/5", "user": "user9248", "ts": 1454513780000, "tid": 172092, "pn": 5}}', 1454513780000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1009284-engl102', 'stk-user8554', 'ENGL 102', 'srcU', '{"html": "هذا مثال كتبته انا عن سورسي<br><br>يمكن لمدرسكم ستايل مختلف<br><br>اسال سكشنك في حوار الويب سي تي العام<br><br>​<span data-fid=\"stk-f1009284-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1009284-0": {"name": "298667394001.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/source-evaluation-eng-102/123053/4", "user": "user8554", "ts": 1331891762000, "tid": 123053, "pn": 4}}', 1331891762000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1139906-engl102', 'stk-user4492', 'ENGL 102', 'srcU', '{"html": "الله يهديك وين ماحصلت سورسات لموضوعك !<br>موضوعك يحمّس إنك تكتب ومع ذلك ماكتبت عنه للحين -_-<br><br>أجل اللي موضوعه :<br>solar wind and its relationship to earth’s climate<br>وش يقول -_- 😦<br><br>على العموم ، قسّم الريبورت إلى :<br>1- آثآر اقتصادية<br>ومنها تتفرع أ- الصناعية و ب- الزراعيه والخ .<br>2- آثآر صحية على الانسان ( نقص الأكل ، الأمراض تكثر مع كثرة المطر؟ )<br>ممكن تحط معه ، 3- آثآر سياسية ( نقص الماء واللجوء لاحتلال الدول )<br>4- هذي من عندك 😛<br><br>#1<br>How does weather &amp; climate affect people<br><br>#2<br>The Effects of Weather on Health<br><br>باقي السورسات يمديك تبحث عنها 😆<br><br>وبالمرفقات ورقة السورس ايفالويشن،<br>ناقص بس انك تعبيها وتسوي سايتيشن !<br><br>دعواتك ❤️ 🌹<br><br>​<span data-fid=\"stk-f1139906-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1139906-0": {"name": "102-S.Eval.Sheet by typing.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl102/136288/21", "user": "user4492", "ts": 1355414866000, "tid": 136288, "pn": 21}}', 1355414866000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p851190-engl102', 'stk-user6095', 'ENGL 102', 'srcP', '{"html": "هذاا الملف اللي نزله لناا كيفن موور …<br><br>ياا شبااب لاا تنسوناا من الدعااء<br><br>بالتوفيق<br><br>​<span data-fid=\"stk-f851190-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f851190-0": {"name": "A Problem With Wind Power - summary practice.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-practise-final/108227/2", "user": "user6095", "ts": 1307861619000, "tid": 108227, "pn": 2}}', 1307861619000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p851496-engl102', 'stk-alroosi', 'ENGL 102', 'srcP', '{"html": "في المرفقات تلاقون سلايد بسيط لساكشن جوش بيلم … إن شاء الله يفيدكم<br><br>بالتوفيق للجميع 👍<br><br>​<span data-fid=\"stk-f851496-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f851496-0": {"name": "Final Exam.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/dd800ba614407080ec68c92220309804de8b5bfbd5a1e4f73be93fc1070436e7"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-practise-final/108227/6", "user": "AlRoosi", "ts": 1307897169000, "tid": 108227, "pn": 6}}', 1307897169000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
