INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-grade-p1321735-engl102', 'stk-medoalkebsi', 'ENGL 102', 'grade', '{"method": "avg", "items": [{"name": "3 كوزات ريدنق", "pct": 15}, {"name": "3 كوزات رايتنق", "pct": 30}, {"name": "ميدترم(ريدنق)", "pct": 10}, {"name": "الريبورت", "pct": 20}, {"name": "برزنتيشن", "pct": 10}, {"name": "فاينل.(ريدنق)", "pct": 15}], "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-102-introduction-to-report-writing/120479/18", "user": "Medoalkebsi", "ts": 1390526143000, "tid": 120479, "pn": 18}}', 1390526143000, 1794206163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
